f._post$Extender._recordID = f.getItemValue('&PostIdentity;');
  f._post$Extender._action = f._action;
  if (f._action == 'New') f._post$Extender._load();

#fsd_btn_gallery {
  background-image: linear-gradient(#42A1EC, #0070C9) !important;
  background-color: linear-gradient(#42A1EC, #0070C9) !important;
  background: linear-gradient(#42A1EC, #0070C9) !important;
  border: 1px solid #0077CC;
  border-radius: 4px;
  box-sizing: border-box;
  color: #FFFFFF;
  cursor: pointer;
  direction: ltr;
  display: block;
  font-family: "SF Pro Text","SF Pro Icons","AOS Icons","Helvetica Neue",Helvetica,Arial,sans-serif;
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -.022em;
  line-height: 1.47059;
  min-width: 30px;
  overflow: visible;
  padding: 4px 15px;
  text-align: center;
  vertical-align: baseline;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
  white-space: nowrap;
}

#fsd_btn_gallery:disabled {
  cursor: default;
  opacity: .3;
}

#fsd_btn_gallery:hover {
  background-image: linear-gradient(#51A9EE, #147BCD);
  border-color: #1482D0;
  text-decoration: none;
}

#fsd_btn_gallery:active {
  background-image: linear-gradient(#3D94D9, #0067B9);
  border-color: #006DBC;
  outline: none;
}

#fsd_btn_gallery:focus {
  box-shadow: rgba(131, 192, 253, 0.5) 0 0 0 3px;
  outline: none;
}

if @$fileupload <> '' begin
  select @fileTicket = lower(replace(newid(),'-',''));
  insert into @@sysDatabaseName..ticket(ticket, user_id, data, datetime0) values(@fileTicket, @@userID, '@@appDatabaseName', getdate());
  select @script = 'this._ticket = "' + @fileTicket + '";' + @script
  select @invoke = 'FileUploadExtender.UploadExtender.Process.UpdateFile(' + @$fileupload + ',' + @$fileticket + ',' + @$filekey + ',' + @stt_rec + ')' + case when @invoke <> '' then '&' + char(255) + ';' else '' end + @invoke
end

var or$ = f.getItem('status'), vr, ir;
if (!f._$handleStatusRemove) {
  for (ir = or$.options.length - 1; ir >= 0; ir--) {
    vr = or$.options[ir];
    if (vr.value == '*') {
      f._$handleStatusRemove = [vr];
      break;
    }
  }
}

if (f._action != 'View') {
  if (or$.value == '*') or$.value = f.grid._dvHandle;
  for (ir = or$.options.length - 1; ir >= 0; ir--) if (or$.options[ir].value == '*') {
    or$.remove(ir);
    f._$wasRemovedDeletion = true;
    break;
  }
} else f._$wasRemovedDeletion = null;

function create$Upload$Extender(f, key) {
  var o = $get('attachmentID');
  if (!f._upload$Extender) {
    var list = $create(FastBusiness.AjaxControlExtender.UploadExtender, {
      id: o.id + '_UploadExtender',
      parentForm: f,
      source: 'List',
      servicePath: '../AppService/UploadExtender.asmx',
      serviceMethod: 'GetListViewPage',
      uploadHandler: '../AppHandler/UploadExtender.ashx',
      downloadHandler: '../AppHandler/DownloadExtender.ashx',
      uploadField: 'fileupload',
      randomField: 'filekey',
      uploadKey: f._action == 'New' ? '' : key
    }, null, null, o);
      
    f._upload$Extender = list;
    list.add_commandEvent(listView$ExecuteCommand);
  }
}
function listView$ExecuteCommand(sender, e) {
  var action = e.type.Action;
  switch (action) {
    case 'BeforeDownload':
      sender._parentForm.request('ListTicket', 'ListTicket', []);
      break;
    default:
      break;
  }
}

  v.init();
  v.setFormLayout(0);
  this.init(f);
},
onCurrencyChanged: function(sender, e) {
  this.onCurrencySelected(sender, e);
  var c = e.object, f = c._currency.parentForm;
  if (c._baseCurrency == e.type) {
    c._exchangeRate._controlBehavior._set_number(1);
    c.onExchangeRateChanged();
  } 
  else {
    var d = f.getItemValue('ngay_lct');
    if (d) f.request('GetExchangeRate', 'GetExchangeRate', ['ma_nt', 'ngay_lct']);
  }
},
onDateChanged: function(sender, e) {
  var c = e.object, f = c._currency.parentForm;
  if (e.type && (c._currency.value != c._baseCurrency)) f.request('GetExchangeRate', 'DateChanged', ['ma_nt', 'ngay_lct']);
},
